arch-ancienne.nvidia-smi:
#!/bin/sh
case "$1" in
--query-gpu=index*pci.bus_id*) echo 'Field "pci.bus_id" is not a valid field to query.'; exit 2;;
--query-gpu=*) echo '0, Vieille carte, 4096, 10, 6.1';;
-L) echo 'GPU 0: Vieille carte';;
esac

nvidia.nvidia-smi:
#!/bin/sh
case "$1" in
-L) echo 'GPU 0: NVIDIA GeForce RTX 3090 (UUID: GPU-1)';;
--query-gpu=compute_cap) printf '8.6\n8.9\n8.6\n';;
'') echo '| NVIDIA-SMI 570.00   Driver Version: 570.00   CUDA Version: 12.8 |';;
--query-gpu=*) printf '0, NVIDIA GeForce RTX 3090, 24576, 100, 8.6, 00000000:01:00.0, 1, 4, 16, 16, 9751\n1, Carte B, 8192, 5, 7.5, [N/A], [N/A], 3, 8, 16, 7001\n';;
esac

nvidia-jumelles.nvidia-smi:
